(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');
  const chkNormalize = $('#chkNormalize');
  const chkShowSyll = $('#chkShowSyll');

  const result = $('#result');
  const sandWord = $('#sandWord');
  const sandOut = $('#sandOut');
  const sandNote = $('#sandNote');
  const btnOx = $('#btnOx');
  const btnBar = $('#btnBar');

  const examples = [
    'εὐτυχής', 'εὐρυπυλής', 'νεήκης', 'ταναήκης', 'εὐμήκης', 'μεγακήτης',
    'ἀκειροκόμης', 'ἑλλανοδίκης', 'μισογύνης', 'κυανοχαίτης', 'κλυτοτέχνης',
    'λεπτουργής', 'Ναξιουργής', 'Ἀττικουργής', 'Κορινθουργής',
    'ἐμβριθής', 'ἀβαρής', 'ἀηδής', 'ἐνηής',
    'ποδωκής', 'τριπήχης', 'τετραπήχης',
    'ἀσαφής', 'ἀρχιλῃστής', 'ἱπποκορυστής', 'φιλοψευδής',
    'εὐήθης', 'συνήθης', 'κακοήθης', 'φιλαλήθης', 'παναλήθης'
  ];

  // --- Unicode helpers ---
  const tonosMap = {
    'α': 'ά', 'ε': 'έ', 'η': 'ή', 'ι': 'ί', 'ο': 'ό', 'υ': 'ύ', 'ω': 'ώ',
    'Α': 'Ά', 'Ε': 'Έ', 'Η': 'Ή', 'Ι': 'Ί', 'Ο': 'Ό', 'Υ': 'Ύ', 'Ω': 'Ώ'
  };

  function stripDiacritics(s) {
    // Remove combining marks; also normalize Greek tonos/polytonic to base letters.
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').normalize('NFC');
  }

  function normalizeForMatch(s) {
    s = s.trim();
    if (!s) return '';
    // Keep Greek letters; keep spaces/hyphens for phrases.
    s = s.replace(/[^\p{Script=Greek}\s\-·'’]/gu, '');
    return chkNormalize.checked ? stripDiacritics(s) : s;
  }

  function lastVowelGroupIndex(word) {
    // Find last Greek vowel (including η ω etc.) in the string.
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    for (let i = word.length - 1; i >= 0; i--) {
      const ch = word[i];
      if (vowels.includes(ch)) return i;
    }
    return -1;
  }

  function makeOxytoneish(original) {
    // Add tonos to the last vowel letter (toy behavior).
    if (!original.trim()) return '';
    // Work on NFC; strip combining marks first so we don't stack.
    let s = stripDiacritics(original);
    const i = lastVowelGroupIndex(s);
    if (i < 0) return original;
    const ch = s[i];
    const accented = tonosMap[ch] || ch;
    s = s.slice(0, i) + accented + s.slice(i + 1);
    return s;
  }

  function makeBarytoneish(original) {
    // Remove tonos/polytonic marks (toy behavior).
    return stripDiacritics(original);
  }

  function roughSyllables(word) {
    // Very rough: split before vowel groups; not philologically correct.
    const w = stripDiacritics(word);
    const vowels = /[αεηιουωΑΕΗΙΟΥΩ]/;
    let out = [];
    let cur = '';
    for (let i = 0; i < w.length; i++) {
      const ch = w[i];
      cur += ch;
      const next = w[i + 1] || '';
      if (vowels.test(ch) && next && !vowels.test(next) && next !== ' ') {
        // keep going; don't split yet
      }
      // split when we have a vowel and next is a vowel or space or end
      if (vowels.test(ch) && (!next || vowels.test(next) || next === ' ' || next === '-' || next === '·')) {
        out.push(cur);
        cur = '';
      }
      if (ch === ' ' || ch === '-' || ch === '·') {
        if (cur.trim()) out.push(cur);
        cur = '';
      }
    }
    if (cur) out.push(cur);
    return out.filter(x => x !== '');
  }

  // --- Rule toy ---
  function analyzeWord(raw) {
    const cleaned = raw.trim();
    const norm = normalizeForMatch(cleaned);

    if (!cleaned) {
      return { ok: false, msg: 'Type a word first.' };
    }

    // Known special cases from the passage
    const special = {
      'ποδωκης': {
        label: 'special tradition',
        tendency: 'barytone (by tradition)',
        rule: 'Herodian: formed from ὠκύς so it “ought” to be oxytone, but tradition reads it barytone (esp. Achilles).'
      },
      'νεηκης': {
        label: 'special tradition',
        tendency: 'barytone (by tradition)',
        rule: 'Herodian: from ἀκή it “ought” to be oxytone, yet tradition barytones νεήκης / ταναήκης by assimilation.'
      },
      'ταναηκης': {
        label: 'special tradition',
        tendency: 'barytone (by tradition)',
        rule: 'Herodian: tradition barytones it (assimilation to εὐμήκης etc.).'
      }
    };

    const key = stripDiacritics(norm).replace(/\s+/g,'');

    // Heuristic families
    const endsWith = (suf) => key.endsWith(suf);

    let guess = { class: 'unk', badge: 'uncertain', tendency: 'uncertain', why: [] };

    if (special[key]) {
      const sp = special[key];
      guess = {
        class: 'bar',
        badge: sp.label,
        tendency: sp.tendency,
        why: [sp.rule]
      };
    } else if (endsWith('ουργης')) {
      guess = {
        class: 'oxy',
        badge: '…ουργής',
        tendency: 'oxytone-ish',
        why: ['Pattern match: -ης from ἔργον (…ουργής) is said to be oxytone in the passage.']
      };
    } else if (endsWith('ηχης')) {
      // πῆχυς compounds: -πήχης
      if (key.includes('τριπηχης') || key.includes('τετραπηχης') || key.includes('πηχης')) {
        guess = {
          class: 'bar',
          badge: 'πήχης-family',
          tendency: 'barytone-ish',
          why: ['Herodian: compounds from barytone πῆχυς are barytone (e.g. τριπήχης, τετραπήχης).']
        };
      }
    }

    // -ης from -υς oxytone adjectives (toy: look for common privative/compound prefixes)
    const prefixes = ['α', 'αν', 'εμ', 'εν', 'ευ', 'δυσ', 'πολυ', 'κακο', 'φιλο', 'μισο', 'κυανο', 'κλυτο', 'αρχι', 'υπο', 'προ'];
    const looksCompound = prefixes.some(p => key.startsWith(p));

    if (guess.class === 'unk' && endsWith('ης')) {
      if (looksCompound && (key.includes('αηδης') || key.includes('αβαρης') || key.includes('εμβριθης') || key.includes('ενηης'))) {
        guess = {
          class: 'oxy',
          badge: '-υς → -ής',
          tendency: 'oxytone-ish',
          why: ['Matches an example family in the passage: oxytone -υς adjectives yield oxytone -ης compounds (βριθύς→ἐμβριθής, βαρύς→ἀβαρής, ἡδύς→ἀηδής, ἠΰς→ἐνηής).']
        };
      } else if (looksCompound && (key.endsWith('κομης') || key.endsWith('δικης') || key.endsWith('γυνης') || key.endsWith('χαιτης') || key.endsWith('τεχνης'))) {
        guess = {
          class: 'bar',
          badge: 'gen. -ου type',
          tendency: 'barytone-ish',
          why: ['Toy match to Herodian’s barytone list: -ης from feminine -η bases that lack a neuter and have genitive -ου (e.g. ἀκειροκόμης, ἑλλανοδίκης, μισογύνης, κυανοχαίτης, κλυτοτέχνης).']
        };
      } else {
        guess = {
          class: 'unk',
          badge: 'generic -ης',
          tendency: 'uncertain',
          why: ['Ends in -ης, but no specific pattern matched. Try an example from the buttons.']
        };
      }
    }

    // Build display
    const syll = chkShowSyll.checked ? roughSyllables(cleaned).join('·') : null;

    return {
      ok: true,
      cleaned,
      norm,
      syll,
      guess
    };
  }

  function renderAnalysis(a) {
    if (!a.ok) {
      result.classList.add('empty');
      result.textContent = a.msg;
      return;
    }
    result.classList.remove('empty');

    const badgeClass = a.guess.class;
    const badge = `<span class="badge ${badgeClass}">${escapeHtml(a.guess.badge)}</span>`;

    const lines = [];
    lines.push(`${badge} tendency: ${a.guess.tendency}`);
    lines.push(`input: ${a.cleaned}`);
    if (a.syll) lines.push(`rough syllables: ${a.syll}`);
    lines.push('');
    lines.push('why (toy reasoning):');
    a.guess.why.forEach((w, i) => lines.push(`  ${i+1}. ${w}`));

    // Suggest sandbox outputs
    const ox = makeOxytoneish(a.cleaned);
    const bar = makeBarytoneish(a.cleaned);
    lines.push('');
    lines.push('accent sandbox suggestions:');
    lines.push(`  oxytone-ish: ${ox}`);
    lines.push(`  barytone-ish: ${bar}`);

    result.innerHTML = lines.map(escapeHtmlPreserveTags).join('\n');
  }

  function escapeHtml(s) {
    return String(s)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function escapeHtmlPreserveTags(line) {
    // We only intentionally inject the badge span in the first line.
    // So: escape everything, then re-insert allowed <span class="badge ...">...</span> if present.
    if (line.includes('<span class="badge')) return line; // already safe from our own construction
    return escapeHtml(line);
  }

  function syncSandboxWord() {
    const w = inp.value.trim();
    sandWord.textContent = w || '—';
    sandOut.textContent = w ? w : '—';
  }

  function applySandbox(mode) {
    const w = inp.value.trim();
    if (!w) {
      sandOut.textContent = '—';
      return;
    }
    if (mode === 'ox') {
      sandOut.textContent = makeOxytoneish(w);
      sandNote.textContent = 'Toy: adds tonos to the last vowel letter (not real accentuation).';
    } else {
      sandOut.textContent = makeBarytoneish(w);
      sandNote.textContent = 'Toy: strips diacritics to give a “barytone-ish” plain form.';
    }
  }

  function doAnalyze() {
    const a = analyzeWord(inp.value);
    renderAnalysis(a);
    syncSandboxWord();
  }

  btnAnalyze.addEventListener('click', doAnalyze);
  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') doAnalyze();
  });
  inp.addEventListener('input', syncSandboxWord);

  btnRandom.addEventListener('click', () => {
    const pick = examples[Math.floor(Math.random() * examples.length)];
    inp.value = pick;
    doAnalyze();
  });

  btnClear.addEventListener('click', () => {
    inp.value = '';
    result.classList.add('empty');
    result.textContent = 'Type a word and click Analyze.';
    syncSandboxWord();
    sandNote.textContent = 'Adds an acute (´) to the last vowel group for “oxytone-ish”; removes tonos for “barytone-ish”.';
  });

  btnOx.addEventListener('click', () => applySandbox('ox'));
  btnBar.addEventListener('click', () => applySandbox('bar'));

  chkNormalize.addEventListener('change', doAnalyze);
  chkShowSyll.addEventListener('change', doAnalyze);

  // init
  syncSandboxWord();
})();

