(() => {
const rows = [];
function group(words, family, accent, reason) {
  words.split(' ').forEach(word => rows.push({word, family, accent, reason}));
}
group('Ἔρυτος Ἄνυτος Εὔρυτος Αἴπυτος Ὄρνυτος Μάδυτος Ὤκυτος Ἄφυτος Ἄκυτος', 'short', 'Barytone · acute on the antepenult', 'The passage groups these proper names in -τος, with more than two syllables and short υ in the penult, as barytone.');
group('Βηρυτός κωκυτός Καρδυτός βουλυτός Κορδυτός γωρυτός Κολλυτός', 'long', 'Oxytone · acute on the ultima', 'The passage groups these trisyllables with long υ in the penult as oxytone. The quantity is supplied by the passage.');
group('πτερωτός τορνωτός χρυσωτός αὐλωτός κηρωτός κροκωτός Βοιωτός', 'omega', 'Oxytone · acute on the ultima', 'The passage gives these examples under trisyllables in -τος with ω in the penult.');
group('Ἀποδωτός Ἀραχωτός', 'contrast', 'Oxytone · acute on the ultima', 'These names appear later in the passage, after the trisyllabic ω examples. They have four syllables, so the three-syllable qualification does not apply to them.');
group('φορυτός πινυτός', 'contrast', 'Oxytone · acute on the ultima', 'These simple adjectives are excluded by the qualification “proper names” in the short-υ rule.');
group('ἄλυτος', 'contrast', 'Barytone · acute on the antepenult', 'The passage explicitly says that this compound is proparoxytone.');
group('Σεβέννυτος', 'contrast', 'Barytone · acute on the antepenult', 'The passage explicitly notes that this word exceeds three syllables and is proparoxytone.');
group('ἄροτος βίοτος', 'contrast', 'Barytone · acute on the antepenult', 'These two words are explicitly singled out as proparoxytone near the opening of the passage.');
const key = value => value.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const $ = id => document.getElementById(id);
function show(word) {
  $('word').value = word;
  const row = rows.find(item => key(item.word) === key(word));
  if (!word.trim()) {
    $('form').textContent = 'Enter a Greek example';
    $('accent').textContent = 'No classification for empty input.';
    $('reason').textContent = 'Choose a button below or type a listed word.';
  } else if (!row) {
    $('form').textContent = word.trim();
    $('accent').textContent = 'Not in this example set';
    $('reason').textContent = 'No accent is inferred for an unlisted word. Try an example below.';
  } else {
    $('form').textContent = row.word;
    $('accent').textContent = row.accent;
    $('reason').textContent = row.reason;
  }
}
const notes = {
  short:'More than two syllables, short υ in the penult, and a proper name: keep all three qualifications.',
  long:'Three syllables with long υ in the penult: compare Βηρυτός with Ἄνυτος.',
  omega:'Three syllables with ω in the penult: examples are accented on the last syllable.',
  contrast:'Compare the excluded simple adjectives, the compound, and the longer names. The later four-syllable names are not examples of the three-syllable qualification.'
};
function examples() {
  $('examples').replaceChildren();
  $('familyNote').textContent = notes[$('family').value];
  rows.filter(item => item.family === $('family').value).forEach(item => {
    const button = document.createElement('button'); button.type = 'button';
    button.textContent = item.word; button.addEventListener('click', () => show(item.word));
    $('examples').append(button);
  });
}
$('lookup').addEventListener('submit', event => {event.preventDefault(); show($('word').value);});
$('family').addEventListener('change', examples);
$('reset').addEventListener('click', () => {
  $('word').value = ''; $('family').value = 'short'; examples();
  $('form').textContent = 'Choose a passage example';
  $('accent').textContent = 'Oxytone: accented on the last syllable. Barytone: not accented on the last syllable; it does not mean “add a grave accent.”';
  $('reason').textContent = 'Matching ignores accents, breathings and case. Only listed examples are classified.';
});
examples();
})();

