group('λεπτουργής Ναξιουργής Ἀττικουργής Κορινθουργής', 'from ἔργον', 'oxytone', 'The passage explicitly accents the -ης compounds from ἔργον on the ultima.');
group('ἐμβριθής ἀβαρής ἀηδής ἐνηής', 'oxytone -υς base', 'oxytone', 'The passage pairs βριθύς, βαρύς, ἡδύς and ἠΰς with these oxytone -ης compounds.');
group('ποδώκης', 'qualified tradition', 'barytone in the cited tradition', 'The derivation from ὠκύς suggests oxytone. The passage reports a barytone reading linked to Achilles, then questions its scope using Atalanta in Hesiod (catal. XXVI Marksch.) and Dolon in Iliad Κ 316.');
group('τριπήχης τετραπήχης', 'barytone πῆχυς base', 'barytone', 'Compounds from barytone πῆχυς retain barytone accentuation.');
group('ἀρχιερανιστής μισοδανειστής ἀρχιλῃστής ἱπποκορυστής ἀσαφής ἀντεραστής φιλαθλητής φιλοψευδής', 'retained base accent', 'oxytone', 'These compounds illustrate retention of the accent of a non-monosyllabic base.');
group('Φιλαπελλῆς', 'retained base accent', 'perispomenon · final circumflex', 'The passage pairs Ἀπελλῆς and Φιλαπελλῆς: preserve the circumflex, rather than relabeling every final accent as oxytone.');
group('εὐήθης συνήθης κακοήθης φιλαλήθης παναλήθης', '-ηθης analogy / exception', 'barytone', 'The -ηθης compounds are barytone; φιλαλήθης and παναλήθης follow their analogy despite ἀληθής.');
group('δικαιοκρίτης ὀνειροκρίτης', 'marked exception', 'barytone', 'The passage marks these compounds as exceptions and discusses the anomalous acute of simple κριτής.');
const base = value => value.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const exact = value => value.normalize('NFC').toLowerCase().trim();
const removeAccents = value => value.normalize('NFD').replace(/[̀́͂]/g, '').normalize('NFC');
function finalAcute(value) {
  const letters = Array.from(removeAccents(value).normalize('NFD'));
  let pos = -1;
  letters.forEach((letter, i) => {if (/[αεηιουωΑΕΗΙΟΥΩ]/.test(letter)) pos = i;});
  if (pos < 0) return value;
  while (pos + 1 < letters.length && /[̀-ͯ]/.test(letters[pos + 1])) pos++;
  letters.splice(pos + 1, 0, '́');
  return letters.join('').normalize('NFC');
}
const defaultNote = 'A mark demonstration only; the source form above is authoritative for these examples.';
function sync() {
  const raw = $('inp').value.trim();
  $('sandWord').textContent = raw || '—'; $('sandOut').textContent = raw || '—';
  $('sandNote').textContent = defaultNote;
}
function analyze() {
  const raw = $('inp').value.trim();
  sync();
  $('result').classList.toggle('empty', !raw);
  if (!raw) {$('result').textContent = 'Type a word first.'; return;}
  const key = $('chkNormalize').checked ? base : exact;
  const item = entries.find(row => key(row.word) === key(raw));
  if (!item) {
    $('result').textContent = 'input: ' + raw + '\nNo example matched. This lookup does not infer accents for unlisted words. With matching off, use the source accents and breathings.';
    return;
  }
  const lines = ['source form: ' + item.word, 'classification: ' + item.tendency, 'family: ' + item.label];
  if ($('chkShowSyll').checked) lines.push('passage 1.82: ' + item.rule);
  $('result').textContent = lines.join('\n');
}
$('btnAnalyze').addEventListener('click', analyze);
$('inp').addEventListener('keydown', event => {if (event.key === 'Enter') {event.preventDefault(); analyze();}});
$('inp').addEventListener('input', sync);
$('btnRandom').addEventListener('click', () => {$('inp').value = entries[Math.floor(Math.random() * entries.length)].word; analyze();});
$('btnClear').addEventListener('click', () => {
  $('inp').value = ''; $('result').textContent = 'Type a word and click Analyze.';
  $('result').classList.add('empty'); sync();
});
$('btnOx').addEventListener('click', () => {
  const raw = $('inp').value.trim(); $('sandOut').textContent = raw ? finalAcute(raw) : '—';
  $('sandNote').textContent = 'Demo: final acute added; this does not predict the correct accent of an arbitrary word.';
});
$('btnBar').addEventListener('click', () => {
  const raw = $('inp').value.trim(); $('sandOut').textContent = raw ? removeAccents(raw) : '—';
  $('sandNote').textContent = 'Demo: accent marks removed, breathings and diaeresis preserved. This is not barytone accentuation.';
});
$('chkNormalize').addEventListener('change', analyze);
$('chkShowSyll').addEventListener('change', analyze);
sync();
})();

original.gadget_css:
:root{
  --bg:#0f1220;
  --panel:#171a2b;
  --card:#1d2140;
  --ink:#eef0ff;
  --muted:#b9bce6;
  --faint:#8b90c9;
  --accent:#7dd3fc;
  --accent2:#a78bfa;
  --good:#34d399;
  --warn:#fbbf24;
  --bad:#fb7185;
  --line:rgba(255,255,255,.10);
  --shadow: 0 10px 30px rgba(0,0,0,.35);
  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace;
  --sans: ui-sans-serif, system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, "Noto Sans", "Liberation Sans", sans-serif;
}

*{box-sizing:border-box}

.wrap{
  font-family:var(--sans);
  color:var(--ink);
  background: radial-gradient(1200px 700px at 20% 0%, rgba(167,139,250,.18), transparent 60%),
              radial-gradient(900px 600px at 90% 10%, rgba(125,211,252,.16), transparent 55%),
              linear-gradient(180deg, #0b0d18, var(--bg));
  padding:18px;
  border-radius:16px;
}

.hdr{
  display:flex;
  gap:14px;
  align-items:flex-start;
  padding:14px 14px 6px;
}

h1{font-size:18px; margin:0 0 6px; letter-spacing:.2px}
.sub{margin:0; color:var(--muted); font-size:13px; line-height:1.35}

.panel{
  display:grid;
  grid-template-columns: 1.05fr .95fr;
  gap:14px;
  padding:10px 14px 14px;
}

@media (max-width: 900px){
  .panel{grid-template-columns:1fr}
}

.controls{
  background:linear-gradient(180deg, rgba(255,255,255,.04), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow:var(--shadow);
}

.lbl{display:block; font-size:12px; color:var(--muted); margin-bottom:6px}

.row{display:flex; gap:8px; align-items:center}

input[type="text"]{
  flex:1;
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.14);
  background:rgba(0,0,0,.25);
  color:var(--ink);
  outline:none;
  font-size:16px;
}
input[type="text"]:focus{border-color: rgba(125,211,252,.55); box-shadow:0 0 0 3px rgba(125,211,252,.12)}

.btn{
  padding:10px 12px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.16);
  background:linear-gradient(180deg, rgba(125,211,252,.22), rgba(125,211,252,.10));
  color:var(--ink);
  cursor:pointer;
  font-weight:600;
}
.btn:hover{filter:brightness(1.08)}
.btn:active{transform:translateY(1px)}
.btn.ghost{
  background:rgba(255,255,255,.06);
}

.toggles{display:flex; gap:14px; flex-wrap:wrap; margin-top:10px}
.chk{font-size:12px; color:var(--muted); user-select:none}
.chk input{transform:translateY(1px)}

.hint{margin:10px 0 0; color:var(--faint); font-size:12px; line-height:1.35}
.ex{font-family:var(--mono); color:var(--ink); background:rgba(255,255,255,.06); padding:1px 6px; border-radius:999px; border:1px solid rgba(255,255,255,.10)}

.out{display:flex; flex-direction:column; gap:14px}

.card{
  background:linear-gradient(180deg, rgba(255,255,255,.05), rgba(255,255,255,.02));
  border:1px solid var(--line);
  border-radius:14px;
  padding:14px;
  box-shadow:var(--shadow);
}

.card h2{margin:0 0 8px; font-size:14px; letter-spacing:.2px}

.result{
  font-family:var(--mono);
  font-size:13px;
  line-height:1.45;
  white-space:pre-wrap;
  padding:10px;
  border-radius:12px;
  border:1px dashed rgba(255,255,255,.18);
  background:rgba(0,0,0,.22);
}
.result.empty{color:var(--faint)}

.badge{
  display:inline-block;
  font-family:var(--sans);
  font-size:11px;
  padding:2px 8px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,.14);
  margin-right:6px;
}
.badge.oxy{background:rgba(52,211,153,.14); border-color:rgba(52,211,153,.35)}
.badge.bar{background:rgba(251,191,36,.14); border-color:rgba(251,191,36,.35)}
.badge.unk{background:rgba(148,163,184,.12); border-color:rgba(148,163,184,.28)}

.mini{margin:0 0 10px; color:var(--muted); font-size:12px; line-height:1.35}

.sandbox{display:flex; flex-direction:column; gap:8px}
.sandRow{display:flex; gap:10px; align-items:flex-start}
.tag{min-width:92px; color:var(--muted); font-size:12px; padding-top:2px}
.sandWord,.sandOut{font-family:var(--mono); font-size:15px}
.sandOut{padding:6px 10px; border-radius:12px; border:1px solid rgba(255,255,255,.14); background:rgba(0,0,0,.22)}
.sandNote{color:var(--faint); font-size:12px; line-height:1.35}

.rules{margin:0; padding-left:18px; color:var(--muted); font-size:12px; line-height:1.45}
.rules li{margin:6px 0}

.ftr{padding:0 14px 14px}
summary{cursor:pointer; color:var(--muted); font-size:12px}
.small{color:var(--muted); font-size:12px; line-height:1.45; margin-top:8px}

kbd{
  font-family:var(--mono);
  font-size:12px;
  padding:1px 6px;
  border-radius:8px;
  border:1px solid rgba(255,255,255,.16);
  background:rgba(0,0,0,.25);
}

original.gadget_js:
(() => {
  const $ = (sel) => document.querySelector(sel);

  const inp = $('#inp');
  const btnAnalyze = $('#btnAnalyze');
  const btnRandom = $('#btnRandom');
  const btnClear = $('#btnClear');
  const chkNormalize = $('#chkNormalize');
  const chkShowSyll = $('#chkShowSyll');

  const result = $('#result');
  const sandWord = $('#sandWord');
  const sandOut = $('#sandOut');
  const sandNote = $('#sandNote');
  const btnOx = $('#btnOx');
  const btnBar = $('#btnBar');

  const examples = [
    'εὐτυχής', 'εὐρυπυλής', 'νεήκης', 'ταναήκης', 'εὐμήκης', 'μεγακήτης',
    'ἀκειροκόμης', 'ἑλλανοδίκης', 'μισογύνης', 'κυανοχαίτης', 'κλυτοτέχνης',
    'λεπτουργής', 'Ναξιουργής', 'Ἀττικουργής', 'Κορινθουργής',
    'ἐμβριθής', 'ἀβαρής', 'ἀηδής', 'ἐνηής',
    'ποδωκής', 'τριπήχης', 'τετραπήχης',
    'ἀσαφής', 'ἀρχιλῃστής', 'ἱπποκορυστής', 'φιλοψευδής',
    'εὐήθης', 'συνήθης', 'κακοήθης', 'φιλαλήθης', 'παναλήθης'
  ];

  // --- Unicode helpers ---
  const tonosMap = {
    'α': 'ά', 'ε': 'έ', 'η': 'ή', 'ι': 'ί', 'ο': 'ό', 'υ': 'ύ', 'ω': 'ώ',
    'Α': 'Ά', 'Ε': 'Έ', 'Η': 'Ή', 'Ι': 'Ί', 'Ο': 'Ό', 'Υ': 'Ύ', 'Ω': 'Ώ'
  };

  function stripDiacritics(s) {
    // Remove combining marks; also normalize Greek tonos/polytonic to base letters.
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').normalize('NFC');
  }

  function normalizeForMatch(s) {
    s = s.trim();
    if (!s) return '';
    // Keep Greek letters; keep spaces/hyphens for phrases.
    s = s.replace(/[^\p{Script=Greek}\s\-·'’]/gu, '');
    return chkNormalize.checked ? stripDiacritics(s) : s;
  }

  function lastVowelGroupIndex(word) {
    // Find last Greek vowel (including η ω etc.) in the string.
    const vowels = 'αεηιουωΑΕΗΙΟΥΩ';
    for (let i = word.length - 1; i >= 0; i--) {
      const ch = word[i];
      if (vowels.includes(ch)) return i;
    }
    return -1;
  }

  function makeOxytoneish(original) {
    // Add tonos to the last vowel letter (toy behavior).
    if (!original.trim()) return '';
    // Work on NFC; strip combining marks first so we don't stack.
    let s = stripDiacritics(original);
    const i = lastVowelGroupIndex(s);
    if (i < 0) return original;
    const ch = s[i];
    const accented = tonosMap[ch] || ch;
    s = s.slice(0, i) + accented + s.slice(i + 1);
    return s;
  }

  function makeBarytoneish(original) {
    // Remove tonos/polytonic marks (toy behavior).
    return stripDiacritics(original);
  }

  function roughSyllables(word) {
    // Very rough: split before vowel groups; not philologically correct.
    const w = stripDiacritics(word);
    const vowels = /[αεηιουωΑΕΗΙΟΥΩ]/;
    let out = [];
    let cur = '';
    for (let i = 0; i < w.length; i++) {
      const ch = w[i];
      cur += ch;
      const next = w[i + 1] || '';
      if (vowels.test(ch) && next && !vowels.test(next) && next !== ' ') {
        // keep going; don't split yet
      }
      // split when we have a vowel and next is a vowel or space or end
      if (vowels.test(ch) && (!next || vowels.test(next) || next === ' ' || next === '-' || next === '·')) {
        out.push(cur);
        cur = '';
      }
      if (ch === ' ' || ch === '-' || ch === '·') {
        if (cur.trim()) out.push(cur);
        cur = '';
      }
    }
    if (cur) out.push(cur);
    return out.filter(x => x !== '');
  }

  // --- Rule toy ---
  function analyzeWord(raw) {
    const cleaned = raw.trim();
    const norm = normalizeForMatch(cleaned);

    if (!cleaned) {
      return { ok: false, msg: 'Type a word first.' };
    }

    // Known special cases from the passage
    const special = {
      'ποδωκης': {
        label: 'special tradition',
        tendency: 'barytone (by tradition)',
        rule: 'Herodian: formed from ὠκύς so it “ought” to be oxytone, but tradition reads it barytone (esp. Achilles).'
      },
      'νεηκης': {
        label: 'special tradition',
        tendency: 'barytone (by tradition)',
        rule: 'Herodian: from ἀκή it “ought” to be oxytone, yet tradition barytones νεήκης / ταναήκης by assimilation.'
      },
      'ταναηκης': {
        label: 'special tradition',
        tendency: 'barytone (by tradition)',
        rule: 'Herodian: tradition barytones it (assimilation to εὐμήκης etc.).'
      }
    };

    const key = stripDiacritics(norm).replace(/\s+/g,'');

    // Heuristic families
    const endsWith = (suf) => key.endsWith(suf);

    let guess = { class: 'unk', badge: 'uncertain', tendency: 'uncertain', why: [] };

    if (special[key]) {
      const sp = special[key];
      guess = {
        class: 'bar',
        badge: sp.label,
        tendency: sp.tendency,
        why: [sp.rule]
      };
    } else if (endsWith('ουργης')) {
      guess = {
        class: 'oxy',
        badge: '…ουργής',
        tendency: 'oxytone-ish',
        why: ['Pattern match: -ης from ἔργον (…ουργής) is said to be oxytone in the passage.']
      };
    } else if (endsWith('ηχης')) {
      // πῆχυς compounds: -πήχης
      if (key.includes('τριπηχης') || key.includes('τετραπηχης') || key.includes('πηχης')) {
        guess = {
          class: 'bar',
          badge: 'πήχης-family',
          tendency: 'barytone-ish',
          why: ['Herodian: compounds from barytone πῆχυς are barytone (e.g. τριπήχης, τετραπήχης).']
        };
      }
    }

    // -ης from -υς oxytone adjectives (toy: look for common privative/compound prefixes)
    const prefixes = ['α', 'αν', 'εμ', 'εν', 'ευ', 'δυσ', 'πολυ', 'κακο', 'φιλο', 'μισο', 'κυανο', 'κλυτο', 'αρχι', 'υπο', 'προ'];
    const looksCompound = prefixes.some(p => key.startsWith(p));

    if (guess.class === 'unk' && endsWith('ης')) {
      if (looksCompound && (key.includes('αηδης') || key.includes('αβαρης') || key.includes('εμβριθης') || key.includes('ενηης'))) {
        guess = {
          class: 'oxy',
          badge: '-υς → -ής',
          tendency: 'oxytone-ish',
          why: ['Matches an example family in the passage: oxytone -υς adjectives yield oxytone -ης compounds (βριθύς→ἐμβριθής, βαρύς→ἀβαρής, ἡδύς→ἀηδής, ἠΰς→ἐνηής).']
        };
      } else if (looksCompound && (key.endsWith('κομης') || key.endsWith('δικης') || key.endsWith('γυνης') || key.endsWith('χαιτης') || key.endsWith('τεχνης'))) {
        guess = {
          class: 'bar',
          badge: 'gen. -ου type',
          tendency: 'barytone-ish',
          why: ['Toy match to Herodian’s barytone list: -ης from feminine -η bases that lack a neuter and have genitive -ου (e.g. ἀκειροκόμης, ἑλλανοδίκης, μισογύνης, κυανοχαίτης, κλυτοτέχνης).']
        };
      } else {
        guess = {
          class: 'unk',
          badge: 'generic -ης',
          tendency: 'uncertain',
          why: ['Ends in -ης, but no specific pattern matched. Try an example from the buttons.']
        };
      }
    }

    // Build display
    const syll = chkShowSyll.checked ? roughSyllables(cleaned).join('·') : null;

    return {
      ok: true,
      cleaned,
      norm,
      syll,
      guess
    };
  }

  function renderAnalysis(a) {
    if (!a.ok) {
      result.classList.add('empty');
      result.textContent = a.msg;
      return;
    }
    result.classList.remove('empty');

    const badgeClass = a.guess.class;
    const badge = `<span class="badge ${badgeClass}">${escapeHtml(a.guess.badge)}</span>`;

    const lines = [];
    lines.push(`${badge} tendency: ${a.guess.tendency}`);
    lines.push(`input: ${a.cleaned}`);
    if (a.syll) lines.push(`rough syllables: ${a.syll}`);
    lines.push('');
    lines.push('why (toy reasoning):');
    a.guess.why.forEach((w, i) => lines.push(`  ${i+1}. ${w}`));

    // Suggest sandbox outputs
    const ox = makeOxytoneish(a.cleaned);
    const bar = makeBarytoneish(a.cleaned);
    lines.push('');
    lines.push('accent sandbox suggestions:');
    lines.push(`  oxytone-ish: ${ox}`);
    lines.push(`  barytone-ish: ${bar}`);

    result.innerHTML = lines.map(escapeHtmlPreserveTags).join('\n');
  }

  function escapeHtml(s) {
    return String(s)
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;')
      .replaceAll('"', '&quot;')
      .replaceAll("'", '&#39;');
  }

  function escapeHtmlPreserveTags(line) {
    // We only intentionally inject the badge span in the first line.
    // So: escape everything, then re-insert allowed <span class="badge ...">...</span> if present.
    if (line.includes('<span class="badge')) return line; // already safe from our own construction
    return escapeHtml(line);
  }

  function syncSandboxWord() {
    const w = inp.value.trim();
    sandWord.textContent = w || '—';
    sandOut.textContent = w ? w : '—';
  }

  function applySandbox(mode) {
    const w = inp.value.trim();
    if (!w) {
      sandOut.textContent = '—';
      return;
    }
    if (mode === 'ox') {
      sandOut.textContent = makeOxytoneish(w);
      sandNote.textContent = 'Toy: adds tonos to the last vowel letter (not real accentuation).';
    } else {
      sandOut.textContent = makeBarytoneish(w);
      sandNote.textContent = 'Toy: strips diacritics to give a “barytone-ish” plain form.';
    }
  }

  function doAnalyze() {
    const a = analyzeWord(inp.value);
    renderAnalysis(a);
    syncSandboxWord();
  }

  btnAnalyze.addEventListener('click', doAnalyze);
  inp.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') doAnalyze();
  });
  inp.addEventListener('input', syncSandboxWord);

  btnRandom.addEventListener('click', () => {
    const pick = examples[Math.floor(Math.random() * examples.length)];
    inp.value = pick;
    doAnalyze();
  });

  btnClear.addEventListener('click', () => {
    inp.value = '';
    result.classList.add('empty');
    result.textContent = 'Type a word and click Analyze.';
    syncSandboxWord();
    sandNote.textContent = 'Adds an acute (´) to the last vowel group for “oxytone-ish”; removes tonos for “barytone-ish”.';
  });

  btnOx.addEventListener('click', () => applySandbox('ox'));
  btnBar.addEventListener('click', () => applySandbox('bar'));

  chkNormalize.addEventListener('change', doAnalyze);
  chkShowSyll.addEventListener('change', doAnalyze);

  // init
  syncSandboxWord();
})();
